"""Independent literal byte oracles, never generated by the reassembler."""
from dataclasses import replace
import struct
from packet_pii.capture import RawFrame,TcpPacket,reassemble,decode_tcp


def pkt(seq,payload=b'',flags=0x18,t=1.):
    return TcpPacket(t,'192.0.2.10','198.51.100.20',50001,80,seq,flags,payload)


def test_wraparound_reassembles_exact_payload():
    assert reassemble([pkt(0xfffffffc,b'',2),pkt(0,b'DEF'),pkt(0xfffffffd,b'ABC')])==(b'ABCDEF',False)


def test_data_on_syn_consumes_syn_sequence_number():
    assert reassemble([pkt(100,b'ABC',2),pkt(104,b'DEF')])==(b'ABCDEF',False)


def test_fin_reveals_missing_final_payload():
    data,unsafe=reassemble([pkt(100,flags=2),pkt(101,b'ABC'),pkt(110,flags=0x11)])
    assert data==b'ABC' and unsafe


def test_ipv4_truncation_not_accepted_as_complete_tcp_payload():
    ip=bytearray(20);ip[0]=0x45;ip[9]=6;ip[2:4]=struct.pack('!H',45)
    ip[12:16]=b'\xc0\x00\x02\x01';ip[16:20]=b'\xc6\x33\x64\x01'
    tcp=bytearray(20);tcp[12]=0x50;tcp[13]=0x18
    assert decode_tcp(RawFrame(1.,101,bytes(ip+tcp)+b'ABC')) is None


def test_ipv6_truncation_not_accepted_as_complete_tcp_payload():
    ip=bytearray(40);ip[0]=0x60;ip[6]=6;ip[4:6]=struct.pack('!H',25)
    tcp=bytearray(20);tcp[12]=0x50
    assert decode_tcp(RawFrame(1.,101,bytes(ip+tcp)+b'ABC')) is None

from packet_pii.capture import reassemble_detailed, sequence_offset, split_tcp_sessions


def test_conflict_exposes_safe_prefix_without_changing_legacy_bytes():
    packets = [pkt(400, b'username=alice'), pkt(409, b'bobXX')]
    result = reassemble_detailed(packets)
    assert result.data == b'username=alice'
    assert result.safe_prefix == b'username='
    assert result.unsafe and 'conflicting_overlap' in result.diagnostics


def test_mid_session_and_unseen_end_are_explicit_unknowns():
    result = reassemble_detailed([pkt(123, b'ABC')])
    assert result.safe_prefix == b'ABC' and not result.unsafe
    assert result.diagnostics == ('initial_coverage_unknown', 'final_coverage_unknown')


def test_wrapped_overlap_is_deduplicated_and_offsets_remain_correct():
    result = reassemble_detailed([pkt(0xfffffffd,b'ABCDE'), pkt(0,b'DEF')])
    assert result.data == b'ABCDEF' and not result.unsafe
    assert result.base_seq == 0xfffffffd
    assert sequence_offset(0, result.base_seq) == 3


def reverse(p):
    return replace(p, src=p.dst, dst=p.src, sport=p.dport, dport=p.sport)


def test_changed_syn_separates_reused_tuple_and_legacy_refuses_to_join():
    packets = [pkt(100, flags=2), pkt(101,b'first'), pkt(900,flags=2), pkt(901,b'second')]
    sessions = split_tcp_sessions(packets)
    assert [reassemble(s)[0] for s in sessions] == [b'first', b'second']
    assert reassemble(packets) == (b'', True)


def test_syn_retransmission_and_half_close_do_not_split_session():
    packets = [pkt(100,flags=2), pkt(100,flags=2), reverse(pkt(900,flags=0x12)),
               pkt(101,b'ABC'), pkt(104,flags=0x11), reverse(pkt(901,b'reply')),
               reverse(pkt(906,flags=0x11)), pkt(100,flags=2)]
    sessions = split_tcp_sessions(packets)
    assert sessions == [packets[:-1], packets[-1:]]


def test_reset_and_later_unobserved_connection_are_separate():
    packets = [pkt(100,b'ABC'), pkt(103,flags=4), pkt(800,b'new')]
    sessions = split_tcp_sessions(packets)
    assert len(sessions) == 2
    assert 'reset_observed' in reassemble_detailed(sessions[0]).diagnostics
    assert reassemble_detailed(sessions[0]).unsafe


def test_payload_beyond_fin_is_excluded_from_safe_prefix():
    result = reassemble_detailed([pkt(100,flags=2), pkt(101,b'ABCDEF'), pkt(104,flags=1)])
    assert result.safe_prefix == b'ABC' and result.unsafe


def test_mixed_direction_reassembly_fails_closed():
    result = reassemble_detailed([pkt(100,b'A'), reverse(pkt(100,b'B'))])
    assert result.safe_prefix == b'' and result.diagnostics == ('mixed_directions',)
